fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    let rows = x.len();
    let cols = x[0].len();

    // result has `cols` rows; each result row has `rows` elements.
    let mut result: Vec<Vec<f32>> = Vec::with_capacity(cols);
    for _ in 0..cols {
        result.push(Vec::with_capacity(rows));
    }

    // Fill by reading row-major from input and pushing into the appropriate
    // transposed row.
    for i in 0..rows {
        // Rectangularity is assumed by the problem statement.
        for j in 0..cols {
            result[j].push(x[i][j]);
        }
    }

    result
}